script:
if (typeof login_ref === 'undefined' || login_ref === null ){
    let login_ref;
    let login_text;
}
var homeUrl = Liferay.ThemeDisplay.getCDNHost();
var path = Liferay.ThemeDisplay.getLayoutRelativeURL();
var langPath = path.substr(0, path.lastIndexOf('/'));
if (langPath.includes('/web')){
    langPath = langPath.substr(0, path.lastIndexOf('/web'));
}
if (Liferay.ThemeDisplay.isSignedIn()){
    login_ref = homeUrl + langPath + "/c/portal/logout";
    login_text = "Logout";
} else {
    login_ref = homeUrl + langPath + "/c/portal/login"
    login_text = "Login / Register";
}
document.getElementById('login_button').innerHTML =
"" + login_text + ""
